CREATE TEMP TABLE before_appliance_matches ON COMMIT DROP AS
SELECT x.*,to_jsonb(p) website_before,to_jsonb(t) pim_before, CASE WHEN x.pim_brand_correction THEN (SELECT z.id FROM tj.aiq_products z WHERE z.brand_name=x.target_brand AND z.model=t.model AND z.market=t.market AND z.status='active' AND z.approval_status='approved') ELSE t.id END canonical_pim_id
FROM verified_appliance_matches x JOIN public.products p ON p.id=x.website_id
JOIN tj.aiq_products t ON t.id=x.pim_id
WHERE p.brand_name=x.website_brand AND p.market IS NOT DISTINCT FROM x.website_market AND p.status=x.status
AND t.brand_name=x.brand_name AND t.model=x.model AND t.market=x.market
AND tj_private.pim_web_image_appliance(t) AND p.category=x.website_category AND t.category=x.category
AND x.target_website_category=tj_private.pim_web_category(x.target_pim_category)
AND tj_private.pim_web_key(p.model_number)=tj_private.pim_web_key(t.model)
AND (p.market IS NULL OR p.market=t.market OR (p.market='Canada' AND t.market='CA' AND p.country='CA'))
AND (SELECT count(*) FROM public.products y WHERE tj_private.pim_web_key(y.model_number)=tj_private.pim_web_key(t.model))=1
AND NOT EXISTS(SELECT 1 FROM public.pim_identity_current ic WHERE ic.source_id=t.id AND ic.decision<>'approved')
AND public.brand_resolve(x.target_brand) IS NOT NULL;
-- Canonical BEST records already exist. Copy distinct assets with original dates,
-- retaining every original source row; archive only the five duplicate misbranded products.
CREATE TEMP TABLE copied_best_assets ON COMMIT DROP AS
SELECT i.id original_image_id,gen_random_uuid() copied_image_id,b.canonical_pim_id,b.pim_id,to_jsonb(i) original_asset
FROM before_appliance_matches b JOIN tj.pim_product_images i ON i.product_id=b.pim_id
WHERE b.pim_brand_correction AND b.canonical_pim_id IS NOT NULL
AND NOT EXISTS(SELECT 1 FROM tj.pim_product_images z WHERE z.product_id=b.canonical_pim_id
AND coalesce(nullif(z.cdn_url,''),z.file_url)=coalesce(nullif(i.cdn_url,''),i.file_url));
INSERT INTO tj.pim_product_images
SELECT (jsonb_populate_record(NULL::tj.pim_product_images,c.original_asset||jsonb_build_object('id',c.copied_image_id,'product_id',c.canonical_pim_id))).*
FROM copied_best_assets c;
UPDATE tj.aiq_products t SET status='archived' FROM before_appliance_matches b
WHERE t.id=b.pim_id AND b.pim_brand_correction AND b.canonical_pim_id IS NOT NULL;
UPDATE tj.aiq_products t SET category=b.target_pim_category FROM before_appliance_matches b WHERE t.id=b.pim_id AND t.category IS DISTINCT FROM b.target_pim_category;
UPDATE public.products p SET category=b.target_website_category,brand_name=b.target_brand,brand_canonical_id=public.brand_resolve(b.target_brand),market=b.target_market,write_source='pim_catalog_completion'
FROM before_appliance_matches b WHERE p.id=b.website_id;
DO $check$ BEGIN
IF EXISTS(SELECT 1 FROM before_appliance_matches b JOIN public.products p ON p.id=b.website_id
WHERE (b.website_before - ARRAY['brand_name','brand_canonical_id','market','write_source','updated_at','normalized_brand_name','category']) IS DISTINCT FROM
(to_jsonb(p) - ARRAY['brand_name','brand_canonical_id','market','write_source','updated_at','normalized_brand_name','category']))
THEN RAISE EXCEPTION 'Unexpected non-identity catalog change'; END IF;
IF EXISTS(SELECT 1 FROM before_appliance_matches b JOIN tj.aiq_products t ON t.id=b.pim_id
WHERE (b.pim_before - ARRAY['status','updated_at','category']) IS DISTINCT FROM (to_jsonb(t) - ARRAY['status','updated_at','category']))
THEN RAISE EXCEPTION 'Unexpected non-brand PIM change'; END IF;
END $check$;
INSERT INTO tj_private.pim_web_completion_log(organization_id,pim_product_id,website_product_id,source_updated_at,action,before_values,after_values,detail)
SELECT b.organization_id,b.pim_id,b.website_id,t.source_extracted_at,'verified_identity_match',
jsonb_build_object('pim',b.pim_before,'website',b.website_before),jsonb_build_object('pim',to_jsonb(t),'website',to_jsonb(p)),
jsonb_build_object('operation','resolve_43_remaining_appliance_matches','manufacturer_source',b.evidence_url,'evidence',b.evidence,'exact_model',b.model,'checked_on','2026-10-11','website_status_and_complete_facts_preserved',true,'canonical_pim_id',b.canonical_pim_id,'duplicate_source_retained',true,'copied_assets',(SELECT coalesce(jsonb_agg(jsonb_build_object('original_image_id',c.original_image_id,'copied_image_id',c.copied_image_id)),'[]') FROM copied_best_assets c WHERE c.pim_id=b.pim_id))
FROM before_appliance_matches b JOIN public.products p ON p.id=b.website_id JOIN tj.aiq_products t ON t.id=b.pim_id;
INSERT INTO tj_private.pim_web_completion_queue(pim_product_id,organization_id)
SELECT canonical_pim_id,organization_id FROM before_appliance_matches WHERE canonical_pim_id IS NOT NULL
ON CONFLICT(pim_product_id) DO UPDATE SET queued_at=clock_timestamp(),processed_at=NULL
WHERE tj_private.pim_web_completion_queue.processed_at IS NOT NULL AND tj_private.pim_web_completion_queue.last_error IS NULL;
SELECT count(*) verified_identity_matches,count(*) FILTER(WHERE pim_brand_correction) retained_duplicate_pim_sources,count(*) FILTER(WHERE website_market IS DISTINCT FROM target_market) normalized_markets FROM before_appliance_matches;
COMMIT;
